// ============================================================
// ACCOUNT & INTERNAL ID SYSTEM
// - Company ko "CO000001..." ID milti hai. Tailor/worker ki ID makeTailorId se banti hai (naam-last4).
// - ID system khud banata hai; user ko yaad rakhne ya manually banane ki zaroorat nahi.
// - ID mobile number se bandhi nahi hai: mobile badle to ID wahi rehti hai (changeAccountMobile).
// - Counter sirf aage badhta hai aur deleted accounts ki IDs "retired" list mein jaati hain,
//   isliye delete hui ID dobara kisi ko nahi milti (sabse badi ID delete ho tab bhi).
// NOTE: Ye frontend prototype hai (browser localStorage). Production mein ye backend/database ka kaam hai.
// ============================================================
const ID_PREFIX = { company: "CO" };
const idNumOf = (id) => parseInt(String(id || "").replace(/\D/g, ""), 10) || 0;
const nextInternalId = (kind) => {
    const pre = ID_PREFIX[kind];
    const reg = MOCK_DB.idRegistry || (MOCK_DB.idRegistry = { company: 0, retired: [] });
    const live = MOCK_DB.companyOwners || [];
    const nums = [reg[kind] || 0, ...live.map(a => idNumOf(a.globalId)), ...(reg.retired || []).filter(x => new RegExp("^" + pre + "\\d{6}$").test(String(x))).map(idNumOf)];
    const n = Math.max(...nums) + 1;
    reg[kind] = n;
    saveMockParts();
    return pre + String(n).padStart(6, "0");
};
// Tailor/Worker ID = PURA PEHLA NAAM (First Name) + "-" + mobile ke aakhri 4 digit. Doosra naam (Second Name / surname) ID mein nahi aata.
const makeTailorId = (name, mobile, firstName, companyId) => {
    let units = [];
    if (firstName && String(firstName).trim())
        units = String(firstName).toUpperCase().match(/\p{L}\p{M}*/gu) || [];
    if (!units.length)
        for (const tok of String(name || "").trim().toUpperCase().split(/\s+/)) {
            units = tok.match(/\p{L}\p{M}*/gu) || [];
            if (units.length)
                break;
        }
    const letters = units.join("") || "TAYLO";
    const last4 = String(mobile || "").replace(/\D/g, "").slice(-4).padStart(4, "0");
    const base = `${letters}-${last4}`;
    const used = new Set([...(MOCK_DB.workers || []).filter(w => !companyId || (w && w.companyId === companyId)).map(w => w && w.globalId), ...(((MOCK_DB.idRegistry || {}).retired) || [])].filter(Boolean));
    let id = base, n = 1;
    while (used.has(id)) {
        n += 1;
        id = `${base}-${n}`;
    }
    return id;
};
// ============================================================
// WORKER ADD (seedha) — Admin ya Manager naam + mobile + department bharke worker record banata hai.
