// WORK CYCLE TIMING LOCK — Helper + Admin UI
// ══════════════════════════════════════════
const fmtD = d => toLocalYMD(d);
// ══════════════════════════════════════════
// GRACE PERIOD HELPERS — cycle khatam hone ke baad kitne din tak
// entry allowed rahegi, uske baad wo cycle auto-lock ho jaati hai.
// cycleId format: "YYYY-MM-A" (1-15), "YYYY-MM-B" (16-end), "YYYY-MM-M" (monthly)
// ══════════════════════════════════════════
// Dono formats accept: "YYYY-MM-A|B|M" (Admin/lock ids) aur "YYYY-MM-1|2" / "YYYY-MM" (getCycleOptions keys)
const getCycleEndDate = (cycleId) => {
    if (!cycleId)
        return null;
    const m = String(cycleId).match(/^(\d{4})-(\d{2})(?:-(A|B|M|1|2))?$/);
    if (!m)
        return null;
    const y = parseInt(m[1], 10), mon = parseInt(m[2], 10), suffix = m[3];
    if (suffix === "A" || suffix === "1")
        return new Date(y, mon - 1, 15);
    // "B"/"2" (16–end), "M" aur bina suffix (monthly) — end = month ka last din
    return new Date(y, mon, 0);
};
const isCycleGraceExpired = (cycleId, graceDays) => {
    const end = getCycleEndDate(cycleId);
    if (!end)
        return false;
    const limit = new Date(end);
    limit.setDate(limit.getDate() + (Number.isFinite(graceDays) ? Math.min(7, graceDays) : 3));
    limit.setHours(23, 59, 59, 999);
    return new Date() > limit;
};
// Shared cycle-list generator — Work Entry date-lock ke liye
// globalCycleType ('15days' | 'monthly') ke hisaab se cycles banata hai
const getCycleOptions = (cycleType, count = 8) => {
    const cycles = [];
    const today = new Date();
    if (cycleType === "monthly") {
        for (let i = 0; i < count; i++) {
            const d = new Date(today.getFullYear(), today.getMonth() - i, 1);
            const y = d.getFullYear(), m = d.getMonth();
            const start = `${y}-${String(m + 1).padStart(2, "0")}-01`;
            const endD = new Date(y, m + 1, 0);
            const end = `${y}-${String(m + 1).padStart(2, "0")}-${String(endD.getDate()).padStart(2, "0")}`;
            const label = d.toLocaleString("en-IN", { month: "long", year: "numeric" });
            const key = `${y}-${String(m + 1).padStart(2, "0")}`;
            cycles.push({ key, start, end, label, isCurrent: i === 0 });
        }
    }
    else {
        for (let i = 0; i < count; i++) {
            const monthsBack = Math.floor(i / 2);
            const d = new Date(today.getFullYear(), today.getMonth() - monthsBack, 1);
            const y = d.getFullYear(), m = d.getMonth();
            const endD = new Date(y, m + 1, 0).getDate();
            const monthName = d.toLocaleString("en-IN", { month: "long", year: "numeric" });
            const todayHalf = today.getDate() <= 15 ? 0 : 1;
            let start, end, label, key;
            if (i === 0) {
                if (todayHalf === 0) {
                    start = `${y}-${String(m + 1).padStart(2, "0")}-01`;
                    end = `${y}-${String(m + 1).padStart(2, "0")}-15`;
                    label = `1–15 ${monthName}`;
                    key = `${y}-${String(m + 1).padStart(2, "0")}-1`;
                }
                else {
                    start = `${y}-${String(m + 1).padStart(2, "0")}-16`;
                    end = `${y}-${String(m + 1).padStart(2, "0")}-${String(endD).padStart(2, "0")}`;
                    label = `16–${endD} ${monthName}`;
                    key = `${y}-${String(m + 1).padStart(2, "0")}-2`;
                }
            }
            else {
                let yr2 = today.getFullYear(), mo2 = today.getMonth();
                let half2 = today.getDate() <= 15 ? 0 : 1;
                for (let h = 0; h < i; h++) {
                    if (half2 === 0) {
                        half2 = 1;
                        mo2--;
                        if (mo2 < 0) {
                            mo2 = 11;
                            yr2--;
                        }
                    }
                    else {
                        half2 = 0;
                    }
                }
                const dX = new Date(yr2, mo2, 1);
                const endDX = new Date(yr2, mo2 + 1, 0).getDate();
                const mn2 = dX.toLocaleString("en-IN", { month: "long", year: "numeric" });
                if (half2 === 0) {
                    start = `${yr2}-${String(mo2 + 1).padStart(2, "0")}-01`;
                    end = `${yr2}-${String(mo2 + 1).padStart(2, "0")}-15`;
                    label = `1–15 ${mn2}`;
                    key = `${yr2}-${String(mo2 + 1).padStart(2, "0")}-1`;
                }
                else {
                    start = `${yr2}-${String(mo2 + 1).padStart(2, "0")}-16`;
                    end = `${yr2}-${String(mo2 + 1).padStart(2, "0")}-${String(endDX).padStart(2, "0")}`;
                    label = `16–${endDX} ${mn2}`;
                    key = `${yr2}-${String(mo2 + 1).padStart(2, "0")}-2`;
                }
            }
            cycles.push({ key, start, end, label, isCurrent: i === 0 });
        }
    }
    return cycles;
};
// Kisi bhi entry ki date se seedha uska Work Cycle nikalta hai
// v269: PERF — toLocaleString (Intl) mehnga hai aur getCycleForDate har entry / har operation row par chalta hai; mahine ka naam (saal, mahina) ke hisaab se ek baar banta hai.
const _twMonthNames = new Map();
const twMonthName = (y, m) => {
    const k = y * 12 + m;
    let v = _twMonthNames.get(k);
    if (v === undefined) {
        v = new Date(y, m - 1, 1).toLocaleString("en-IN", { month: "long", year: "numeric" });
        _twMonthNames.set(k, v);
    }
    return v;
};
const getCycleForDate = (dateStr, cycleType) => {
    if (!dateStr)
        return null;
    const [y, m, d] = dateStr.split("-").map(Number);
    if (!y || !m || !d)
        return null;
    const monthName = twMonthName(y, m);
    const mm = String(m).padStart(2, "0");
    const endD = new Date(y, m, 0).getDate();
    if (cycleType === "monthly") {
        return {
            key: `${y}-${mm}`, label: monthName,
            start: `${y}-${mm}-01`, end: `${y}-${mm}-${String(endD).padStart(2, "0")}`,
        };
    }
    if (d <= 15) {
        return { key: `${y}-${mm}-1`, label: `1–15 ${monthName}`, start: `${y}-${mm}-01`, end: `${y}-${mm}-15` };
    }
    return { key: `${y}-${mm}-2`, label: `16–${endD} ${monthName}`, start: `${y}-${mm}-16`, end: `${y}-${mm}-${String(endD).padStart(2, "0")}` };
};
// Cycle key ("YYYY-MM" monthly | "YYYY-MM-1" / "YYYY-MM-2" 15-day) se seedha cycle (start/end/label) —
const getCycleByKey = (key) => {
    if (!key)
        return null;
    const p = String(key).split("-");
    const y = Number(p[0]), m = Number(p[1]);
    if (!y || !m)
        return null;
    const mm = String(m).padStart(2, "0");
    if (p.length >= 3) {
        const day = p[2] === "2" ? "16" : "01";
        return getCycleForDate(`${y}-${mm}-${day}`, "15days");
    }
    return getCycleForDate(`${y}-${mm}-01`, "monthly");
};
// Aaj ke baad aane wali cycles — agle `months` mahine tak (15days => ~6 cycles, monthly => 3 cycles)
const getFutureCycles = (cycleType, months = 3) => {
    const fmt = (d) => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
    const today = new Date();
    const limit = fmt(new Date(today.getFullYear(), today.getMonth() + months, today.getDate()));
    const out = [];
    let cur = getCycleForDate(fmt(today), cycleType);
    for (let i = 0; cur && i < 24; i++) {
        const [y, m, d] = cur.end.split("-").map(Number);
        const nextStart = fmt(new Date(y, m - 1, d + 1));
        if (nextStart > limit)
            break;
        cur = getCycleForDate(nextStart, cycleType);
        if (cur)
            out.push({ ...cur, isFuture: true });
    }
    return out;
};
const withSelectedCycle = (options, selectedKey) => {
    if (!selectedKey || options.some(c => c.key === selectedKey))
        return options;
    const extra = getCycleByKey(selectedKey);
    return extra ? [...options, extra] : options;
};
// ============================================================
// STYLE-BASED ALLOCATION MODEL  (Style → Department → Cycle → Quantity)
//   Allocation ka MASTER Style hai. Form mein sirf Department + Cycle + Quantity; Style current page se aata hai.
//   Scope: Company + Style + Department + Cycle.
//   Style ke us department ke SAARE configured operations ko wahi cycle-quantity automatically milti hai (operation ko alag allocation nahi).
//   Allocated qty sab operations ke liye SAME; actual completed work operation-wise ALAG ho sakta hai.
//   Work Entry: operation select hota hai; check = us operation ki us cycle ki total entries <= cycle allocation.
//   Koi previous/next operation, Cutting/Finishing ya garment-stage dependency nahi.
// Allocation record: { id, companyId, styleId, department, cycleKey, cycleLabel, allocatedQty, remarks, createdAt }  (operationId KABHI nahi)
// ============================================================
const sameCompany = (rec, companyId) => {
    // SECURITY: missing IDs are untrusted legacy data, not globally visible.
    return !!companyId && !!rec?.companyId && rec.companyId === companyId;
};
// ── DEPARTMENT IDENTITY ──────────────────────────────────────────────────
// Department ki asli pehchaan uska ID (line.id) hai. Naam sirf dikhane ke liye hai aur rename ho sakta hai.
// Operations / allocations / entries par "lineId" stamp hota hai; purane data (jisme lineId nahi) ke liye naam se fallback.
const deptIdsByName = (lines, name, companyId) => (lines || []).filter(l => l.name === name && sameCompany(l, companyId)).map(l => l.id);
const recLineId = (rec, lines, companyId) => {
    if (!rec)
        return "";
    if (rec.lineId && (lines || []).some(l => l.id === rec.lineId))
        return rec.lineId;
    const nm = rec.line || rec.department || "";
    return (lines || []).find(l => l.name === nm && sameCompany(l, companyId || rec.companyId))?.id || "";
};
const opLineIdById = (id) => (MOCK_DB.operations || []).find(o => o.id === id)?.lineId || "";
// Worker kisi department mein ENROLLED hai? — workerLineMap (Team tab / Add Worker se bana) hi single source of truth hai.
const isWorkerInDept = (worker, deptName, lines, workerLineMap, companyId, lineId) => {
    if (!worker)
        return false;
    // v84: lineId purana/stale ho to bhi department NAAM se match — dono ka union
    const ids = [...new Set([...(lineId ? [lineId] : []), ...(deptName ? deptIdsByName(lines, deptName, companyId) : [])])];
    if (!ids.length)
        return false;
    const enrolled = workerLineMap?.[worker.id] || [];
    return ids.some(id => enrolled.includes(id));
};
// Naya department naam: "Dept N" — sabse chhota N jo abhi use mein nahi (delete ke baad duplicate nahi banta)
const nextDeptName = (lines) => {
    const used = new Set((lines || []).map(l => String(l.name || "").trim().toLowerCase()));
    let n = 1;
    while (used.has("dept " + n))
        n++;
    return "Dept " + n;
};
// Naam validate: khaali nahi, 40 char tak, company mein unique (case-insensitive). excludeId = rename karte waqt apni line
const validateDeptName = (name, lines, companyId, excludeId) => {
    const nm = String(name || "").trim().replace(/\s+/g, " ");
    if (!nm)
        return { ok: false, msg: "Department ka naam likho." };
    if (nm.length > 40)
        return { ok: false, msg: "Naam 40 characters se chhota rakho." };
    if ((lines || []).some(l => l.id !== excludeId && sameCompany(l, companyId) && String(l.name || "").trim().toLowerCase() === nm.toLowerCase()))
        return { ok: false, msg: `"${nm}" naam ka department pehle se hai.` };
    return { ok: true, name: nm };
};
// Naya department record banao (Dashboard Setting aur Departments dono yahin se)
const buildNewDept = ({ lines, user, name, code }) => {
    const list = lines || [];
    const v = String(name || "").trim() ? validateDeptName(name, list, user?.companyId) : { ok: true, name: nextDeptName(list) };
    if (!v.ok)
        return v;
    return { ok: true, dept: {
            id: uid("d"), companyId: user?.companyId, lineCode: code, name: v.name,
            color: DEPT_COLOR_OPTIONS_PROFILE[list.length % DEPT_COLOR_OPTIONS_PROFILE.length],
            deptHead: "", workerCount: 0, dailyTarget: 0,
        } };
};
