// Purane saved data (operations / entries / allocations) par lineId ek baar stamp karo
(function migrateLineIds() {
    const lines = PERSISTED?.lines || MOCK_DB.lines;
    const stamp = (r) => {
        if (!r || r.lineId)
            return r;
        const id = recLineId(r, lines, r.companyId);
        return id ? { ...r, lineId: id } : r;
    };
    let changed = false;
    MOCK_DB.operations.forEach((o, i) => { const n = stamp(o); if (n !== o) {
        MOCK_DB.operations[i] = n;
        changed = true;
    } });
    if (PERSISTED) {
        if (Array.isArray(PERSISTED.entries))
            PERSISTED.entries = PERSISTED.entries.map(stamp);
        if (Array.isArray(PERSISTED.deptAllocations))
            PERSISTED.deptAllocations = PERSISTED.deptAllocations.map(stamp);
    }
    if (changed)
        saveMockParts();
})();
const isDeptAlloc = (a) => !a.operationId && !!a.department && !!a.cycleKey;
const opLineById = (id) => (MOCK_DB.operations || []).find(o => o.id === id)?.line || "";
// Style ke configured operations (style.opNames — Styles → Add Operations se sync hota hai). Configure nahi hua (undefined) to department ke saare operations.
const styleHasOp = (style, op) => !op ? false
    : Array.isArray(style?.opNames) ? style.opNames.includes(op.name)
        : Array.isArray(style?.processes) ? style.processes.some(p => p.name === op.name)
            : true;
// Style ke configured operations, ek department (ya department=null to sab) ke
const getStyleDeptOps = (style, department, companyId, allocs, cycleKey) => {
    // Style mein combos hon to sirf combo ke operations (combo ke bahar ke purane operations nahi dikhte).
    const combos = Array.isArray(style?.combos) ? style.combos : [];
    const hasCombos = combos.length > 0;
    const inCombo = (op) => !hasCombos || combos.some(c => (c.opNames || []).includes(op.name));
    const allocatedCombo = (op) => !hasCombos || !allocs || !cycleKey || (allocs || []).some(a => isDeptAlloc(a) && a.styleId === style.id && a.cycleKey === cycleKey && sameCompany(a, companyId) && a.department === (department || op.line) && a.comboId && Array.isArray(a.comboOps) && a.comboOps.includes(op.name));
    const ops = (MOCK_DB.operations || []).filter(inCombo);
    const own = ops.filter(op => (!department || op.line === department) && sameCompany(op, companyId) && styleHasOp(style, op));
    if (!department || own.length > 0)
        return own.filter(allocatedCombo);
    // Department ke apne koi operations define hi nahi → style ke wahi operations us department ki allocation ke liye bhi chalenge (alag se banane ki zaroorat nahi)
    if (ops.some(op => op.line === department && sameCompany(op, companyId)))
        return own;
    const lineId = (MOCK_DB.lines || []).find(l => l.name === department && sameCompany(l, companyId))?.id;
    return ops.filter(op => sameCompany(op, companyId) && styleHasOp(style, op))
        .map(op => ({ ...op, line: department, lineId })).filter(allocatedCombo);
};
const allocLineOf = (a) => a?.department || "";
// ── COMBO = Style ke operations ka named group ({ id, name, opNames:[...] } — sharedStyles[i].combos) ──
const allocCoversOp = (a, opName) => !a?.comboId || !Array.isArray(a?.comboOps) || !opName || a.comboOps.includes(opName);
// Carry-forward: allocation par per-operation carryIn (pichli cycle se aaya) / carryOut (agli cycle mein gaya) — { [opName]: qty }
const allocOpQty = (a, opName) => toNum(a?.allocatedQty) + toNum(a?.carryIn?.[opName]) - toNum(a?.carryOut?.[opName]);
const allocHasCarry = (a) => Object.values(a?.carryIn || {}).some(v => toNum(v) > 0) || Object.values(a?.carryOut || {}).some(v => toNum(v) > 0);
// Carry kis allocation mein gaya: user ne form mein jo department/cycle chuni (carryToId); purani carry (carryToId nahi) ke liye agli cycle, wahi department/combo.
const carryTargetOf = (allocs, a, cycleType) => {
    if (!a)
        return null;
    const list = allocs || [];
    if (a.carryToId && Object.values(a.carryOut || {}).some(v => toNum(v) > 0)) {
        const t = list.find(x => x.id === a.carryToId && x.id !== a.id);
        if (t)
            return t;
    }
    const cyc = getCycleByKey(a.cycleKey);
    const nextCyc = cyc && getCycleForDate(nextDayYMD(cyc.end), cycleType);
    return (nextCyc && list.find(x => x.id !== a.id && x.styleId === a.styleId && isDeptAlloc(x) && x.department === a.department && x.cycleKey === nextCyc.key && x.comboId === a.comboId && sameCompany(x, a.companyId))) || null;
};
// Is allocation (t) mein carry bhejne wali allocations (chuni hui department/cycle se + purani pichli-cycle wali)
const carryOriginsOf = (allocs, t, cycleType) => {
    const list = allocs || [];
    const direct = list.filter(x => x.id !== t.id && x.carryToId === t.id && Object.values(x.carryOut || {}).some(v => toNum(v) > 0));
    const cyc = getCycleByKey(t.cycleKey);
    const prevCyc = cyc && getCycleForDate(prevDayYMD(cyc.start), cycleType);
    const legacy = prevCyc ? list.filter(x => x.id !== t.id && !x.carryToId && x.styleId === t.styleId && isDeptAlloc(x) && x.department === t.department && x.cycleKey === prevCyc.key && x.comboId === t.comboId && sameCompany(x, t.companyId)) : [];
    return [...direct, ...legacy.filter(l => !direct.includes(l))];
};
// Card par dikhne wali allocation qty: carry-forward (aaya/gaya) judne ke baad ki asli qty. Carry na ho to wahi allocatedQty.
const allocDisplayQty = (a) => {
    if (!allocHasCarry(a))
        return toNum(a?.allocatedQty);
    const ops = Array.isArray(a?.comboOps) && a.comboOps.length ? a.comboOps : [...new Set([...Object.keys(a?.carryIn || {}), ...Object.keys(a?.carryOut || {})])];
    return ops.length ? Math.max(...ops.map(n => allocOpQty(a, n))) : toNum(a?.allocatedQty);
};
// SELF-HEAL: carry (carryOut) kabhi bhi us operation ke asli balance (allocatedQty + carryIn − done) se zyada nahi ho sakta.
const healCarryAllocs = (allocs, entries, cycleType) => {
    const list = allocs || [];
    const patch = {}; // id -> { carryOut?, carryIn? }
    const get = (x) => ({ ...x, ...(patch[x.id] || {}) });
    list.forEach(a0 => {
        if (!isDeptAlloc(a0) || !Object.values(a0.carryOut || {}).some(v => toNum(v) > 0))
            return;
        const tgt0 = carryTargetOf(list, a0, cycleType);
        Object.keys(a0.carryOut || {}).forEach(n => {
            const a = get(a0), out = toNum(a.carryOut?.[n]);
            if (out <= 0)
                return;
            const cap = Math.max(0, toNum(a.allocatedQty) + toNum(a.carryIn?.[n]) - opDoneByName(entries, a, n));
            if (out <= cap)
                return;
            const diff = out - cap;
            const nx0 = tgt0;
            const nx = nx0 && get(nx0);
            if (nx && allocOpQty(nx, n) - diff < opDoneByName(entries, nx, n))
                return; // agli cycle mein entries ho chuki hain — chhedo mat
            const setMap = (m, k, v) => { const r = { ...(m || {}) }; if (v > 0)
                r[k] = v;
            else
                delete r[k]; return r; };
            patch[a0.id] = { ...(patch[a0.id] || {}), carryOut: setMap(a.carryOut, n, cap) };
            if (nx)
                patch[nx0.id] = { ...(patch[nx0.id] || {}), carryIn: setMap(nx.carryIn, n, toNum(nx.carryIn?.[n]) - diff) };
        });
    });
    if (!Object.keys(patch).length)
        return allocs;
    return list.map(x => patch[x.id] ? { ...x, ...patch[x.id] } : x);
};
const nextDayYMD = (ymd) => { const [y, m, d] = String(ymd).split("-").map(Number); return toLocalYMD(new Date(y, (m || 1) - 1, (d || 1) + 1)); };
const prevDayYMD = (ymd) => { const [y, m, d] = String(ymd).split("-").map(Number); return toLocalYMD(new Date(y, (m || 1) - 1, (d || 1) - 1)); };
// Carry-forward ka link toddo (allocation delete / combo-cycle badalne se pehle): is allocation ki carryOut agli cycle ki carryIn se hat jaati hai,
const unwindAllocCarry = (allocs, target, entries, cycleType) => {
    const list = allocs || [];
    if (!target || !allocHasCarry(target))
        return { ok: true, allocs: list };
    const nx = carryTargetOf(list, target, cycleType);
    const origins = carryOriginsOf(list, target, cycleType);
    const sub = (m, k, v) => { const r = { ...(m || {}) }; const q = toNum(r[k]) - v; if (q > 0)
        r[k] = q;
    else
        delete r[k]; return r; };
    let nxIn = nx ? { ...(nx.carryIn || {}) } : null;
    const pvOut = {};
    origins.forEach(o => { pvOut[o.id] = { ...(o.carryOut || {}) }; });
    for (const n of Object.keys(target.carryOut || {})) {
        const out = toNum(target.carryOut[n]);
        if (out <= 0 || !nx)
            continue;
        if (allocOpQty(nx, n) - out < opDoneByName(entries, nx, n))
            return { ok: false, msg: `Jis allocation mein carry gaya (\"${n}\") uski entries ho chuki hain — carry-forward hataya nahi ja sakta.` };
        nxIn = sub(nxIn, n, out);
    }
    for (const n of Object.keys(target.carryIn || {})) {
        let rem = toNum(target.carryIn[n]);
        for (const o of origins) {
            if (rem <= 0)
                break;
            const take = Math.min(toNum(pvOut[o.id][n]), rem);
            if (take > 0) {
                pvOut[o.id] = sub(pvOut[o.id], n, take);
                rem -= take;
            }
        }
    }
    return { ok: true, allocs: list.map(x => x.id === target.id ? { ...x, carryIn: {}, carryOut: {}, carryToId: undefined } : (nx && x.id === nx.id) ? { ...x, carryIn: nxIn } : pvOut[x.id] ? { ...x, carryOut: pvOut[x.id] } : x) };
};
const entryOpName = (e) => (MOCK_DB.operations || []).find(o => o.id === e?.operationId)?.name || e?.operationName || e?.operation || "";
// Style + Department + Cycle (+ operation ho to usko cover karne wali) allocation. Ek se zyada combo-allocation mile to qty jud jaati hai.
const findAllocation = (allocs, styleId, department, cycleKey, companyId, opName) => {
    const list = (allocs || []).filter(a => isDeptAlloc(a) && a.styleId === styleId && a.department === department && (cycleKey === undefined || a.cycleKey === cycleKey) && sameCompany(a, companyId) && allocCoversOp(a, opName));
    if (!list.length)
        return undefined;
    if (opName && cycleKey !== undefined)
        return { ...list[0], allocatedQty: list.reduce((sum, a) => sum + allocOpQty(a, opName), 0) }; // carry-forward ke saath
    if (list.length <= 1 || cycleKey === undefined)
        return list[0];
    return { ...list[0], allocatedQty: list.reduce((sum, a) => sum + toNum(a.allocatedQty), 0) };
};
// Is allocation ki cycle mein ek operation (naam se) ka ab tak ka kaam
const _opDoneCache = new WeakMap();
const opDoneByName = (entries, alloc, opName) => {
    const cyc = getCycleByKey(alloc.cycleKey);
    if (!cyc)
        return 0;
    if (!Array.isArray(entries))
        return 0;
    let m = _opDoneCache.get(entries);
    if (!m) {
        m = new Map();
        _opDoneCache.set(entries, m);
    }
    const k = `${alloc.styleId}|${alloc.companyId}|${alloc.department}|${alloc.cycleKey}`;
    let by = m.get(k);
    if (!by) {
        by = {};
        entries.forEach(e => {
            if (e.styleId === alloc.styleId && isCountedEntry(e) && sameCompany(e, alloc.companyId) && e.date >= cyc.start && e.date <= cyc.end && entryInDept(e, alloc.department)) {
                const n = entryOpName(e);
                by[n] = (by[n] || 0) + getEntryPieces(e);
            }
        });
        m.set(k, by);
    }
    return by[opName] || 0;
};
