// STYLE WORK DOWNLOAD — Style Report ke style card se: cycle-wise → combo-wise → operation/department-wise pieces aur value (tailor ki detail nahi); combo ke bahar ke operations har cycle mein sabse neeche
// Style ka work: combo-wise ek jagah — combo → operation → (cycle, department, tailor, rate) = qty, total. Screen aur PDF/Excel dono yahi use karte hain.
const buildStyleWorkTree = (style, entries, cycleOf) => {
    const order = (Array.isArray(style?.processes) ? style.processes : []).map(p => p.name);
    const combos = Array.isArray(style?.combos) ? style.combos : [];
    const sortOps = (names) => [...order.filter(n => names.includes(n)), ...names.filter(n => !order.includes(n)).sort()];
    const ops = new Map(); // operation -> Map(cycle||dept||tailor||rate -> row)
    entries.forEach(e => {
        const c = (typeof cycleOf === "function" && cycleOf(e)) || null;
        const op = entryOpName(e) || e.operation || "-";
        const dept = e.line || e.department || "-";
        const tailor = e.staffId || e.workerName || "-";
        const rate = getEntryRate(e);
        if (!ops.has(op))
            ops.set(op, new Map());
        const m = ops.get(op);
        const k = [c?.key || "-", dept, tailor, rate].join("||");
        const t = m.get(k) || { cycle: c?.label || "-", start: String(c?.start || ""), dept, tailor, rate, pcs: 0, val: 0 };
        t.pcs += getEntryPieces(e);
        t.val = roundMoney(t.val + getEntryAmount(e));
        m.set(k, t);
    });
    const used = new Set();
    const groups = [];
    let totalPcs = 0, totalVal = 0;
    const addGroup = (name, opNames, isCombo) => {
        const present = sortOps(opNames.filter(n => ops.has(n) && !used.has(n))); // ek operation sirf ek baar — do combos mein ho to double count nahi
        if (!present.length)
            return;
        let gPcs = 0, gVal = 0;
        const opList = present.map(op => {
            used.add(op);
            const rows = [...ops.get(op).values()].sort((x, y) => x.start.localeCompare(y.start) || String(x.dept).localeCompare(String(y.dept)) || String(x.tailor).localeCompare(String(y.tailor)) || x.rate - y.rate);
            const pcs = rows.reduce((t, r) => t + r.pcs, 0);
            const val = roundMoney(rows.reduce((t, r) => t + r.val, 0));
            gPcs += pcs;
            gVal = roundMoney(gVal + val);
            return { op, rows, pcs, val };
        });
        groups.push({ name, isCombo, ops: opList, pcs: gPcs, val: gVal });
        totalPcs += gPcs;
        totalVal = roundMoney(totalVal + gVal);
    };
    combos.forEach(c => addGroup(c.name || "Combo", c.opNames || [], true));
    // Jo operation kisi combo mein nahi — sabse neeche, bina combo ke
    addGroup("No combo", [...ops.keys()].filter(n => !used.has(n)), false);
    return { groups, totalPcs, totalVal };
};
const buildStyleWorkRows = (style, entries, cycleOf) => {
    const { groups, totalPcs, totalVal } = buildStyleWorkTree(style, entries, cycleOf);
    const rows = [["Combo", "Operation", "Cycle", "Department", "Tailor", "Rate", "Qty", "Total"]];
    const bold = new Set();
    groups.forEach(g => {
        g.ops.forEach(o => o.rows.forEach(t => rows.push([g.name, o.op, t.cycle, t.dept, t.tailor, t.rate.toFixed(2), t.pcs, t.val.toFixed(2)])));
        bold.add(rows.length);
        rows.push([`${g.name} \u2014 Total`, "", "", "", "", "", g.pcs, g.val.toFixed(2)]);
    });
    bold.add(rows.length);
    rows.push(["GRAND TOTAL", "", "", "", "", "", totalPcs, totalVal.toFixed(2)]);
    return { rows, bold, totalPcs, totalVal };
};
// Style page ke Operations section ke andar: har operation ke neeche uska kaam — Cycle | Dept | Tailor | Rate | Qty | Total
// STYLE TABLES — SHARED SPEC: columns ke naam + chaudai ek hi jagah. Screen, PDF aur Excel sab yahin se lete hain (kuch badalna ho to sirf yahan).
const SWR_FR = [1.05, 1, 1.3, 0.72, 1];
const SWR_COLS = SWR_FR.map(v => `minmax(0,${v}fr)`).join(" ");
const STYLE_OPS_COLS = ["Cycle", "Dept", "Tailor", "Qty", "Total"];
const STYLE_ALLOC_COLS = ["Operation", "Current", "Next", "Prev", "Total"];
const swrCell = twCell(1, { display: "flex", alignItems: "center" }); // flex: row stretch hone par bhi text beech mein, line poori unchai tak
const swrShort = (l) => String(l || "-").replace(/[A-Za-z]{4,}/g, m => m.slice(0, 3)).replace(/\s\d{4}$/, "");
const swrMoney = (n) => "\u20B9" + toNum(n).toLocaleString("en-IN", { maximumFractionDigits: 2 });
const swrQty = (n) => toNum(n).toLocaleString("en-IN");
const StyleWorkHead = () => React.createElement(TwTblHead, { cols: SWR_COLS, labels: STYLE_OPS_COLS, rightFrom: 3, style: { borderTop: "1px solid " + TW_TBL.headDivider } });
const StyleOpWork = ({ name, rate, data, alloc }) => (React.createElement("div", null,
    React.createElement("div", { className: "flex items-center justify-between gap-2 px-3 py-2", style: { background: "#E6F4EA", borderBottom: "1px solid #CBE5D3" } },
        React.createElement("p", { style: { margin: 0, minWidth: 0, fontSize: 13, fontWeight: 800, color: TW_GREEN, overflowWrap: "anywhere" } },
            name,
            React.createElement("span", { style: { marginLeft: 8, color: TW_GREEN, fontWeight: 800 } }, "\u20B9" + rate)),
        React.createElement("p", { style: { margin: 0, fontSize: 13, fontWeight: 800, whiteSpace: "nowrap", color: TW_GREEN } }, swrQty(alloc) + "/" + swrQty(data ? data.pcs : 0))),
    data && data.rows.map((r, i) => (React.createElement("div", { key: i, style: { display: "grid", gridTemplateColumns: SWR_COLS, background: "#FFFFFF", borderBottom: "1px solid #E5E7EB", alignItems: "stretch" } },
        React.createElement("div", { style: { ...swrCell, borderLeft: 0, paddingLeft: 10 } }, swrShort(r.cycle)),
        React.createElement("div", { style: { ...swrCell, fontWeight: 800 } }, r.dept),
        React.createElement("div", { style: { ...swrCell } }, r.tailor),
        React.createElement("div", { style: { ...swrCell, textAlign: "right", justifyContent: "flex-end" } }, swrQty(r.pcs)),
        React.createElement("div", { style: { ...swrCell, textAlign: "right", justifyContent: "flex-end", fontWeight: 800, color: TW_GREEN } }, swrMoney(r.val)))))));
// Style Excel — app ke Style page jaisa (PDF wala hi model): Operations (combo → operation alloc/done → kaam ki rows) + Allocation cards. Screen par jo nahi hai (Grand total wagairah) wo bhi nahi.
const buildStyleScreenRows = (style, entries, cycleOf, extra) => {
    const rs = (v) => "Rs " + toNum(v).toLocaleString("en-IN", { maximumFractionDigits: 2 });
    const { blocks } = buildStyleOpsModel(style, entries, cycleOf, extra?.allocs, extra?.companyId);
    const rows = [["", "", "", "", ""]];
    const bold = new Set(), dark = new Set(), head = new Set();
    const spacer = () => { if (rows.length > 1) rows.push(["", "", "", "", ""]); };
    blocks.forEach(b => {
        spacer();
        head.add(rows.length);
        rows.push([b.title + "  |  " + b.ops.length + " operations", "", "", b.alloc > 0 ? "Alloc " + b.alloc.toLocaleString("en-IN") : "Alloc -", b.val > 0 ? rs(b.val) : "-"]);
        head.add(rows.length);
        rows.push([...STYLE_OPS_COLS]);
        b.ops.forEach(o => {
            dark.add(rows.length);
            rows.push([o.name + "  Rs " + o.rate, "", "", o.alloc.toLocaleString("en-IN") + "/" + o.pcs.toLocaleString("en-IN"), ""]);
            o.rows.forEach(t => rows.push([swrShort(t.cycle), t.dept, t.tailor, t.pcs, rs(t.val)]));
        });
    });
    const cards = extra ? buildStyleAllocCards(style || {}, extra.allocs, extra.companyId, extra.allEntries || []) : [];
    if (cards.length) {
        spacer();
        bold.add(rows.length);
        rows.push(["Allocation", "", "", "", ""]);
        cards.forEach((a, ci) => {
            if (ci)
                spacer();
            head.add(rows.length);
            rows.push([[a.dept, a.cycle, a.combo].filter(Boolean).join("  |  "), "", "", "", toNum(a.qty)]);
            if (!a.rows) {
                rows.push(["Combo select nahi hai", "", "", "", ""]);
                return;
            }
            head.add(rows.length);
            rows.push([...STYLE_ALLOC_COLS]);
            a.rows.forEach(r => {
                dark.add(rows.length);
                rows.push([r[0], r[1], r[2], r[3], r[4]]);
                (r[5] || []).forEach(t => rows.push([t[0], "", "", t[1], "Rs " + toNum(t[2]).toLocaleString("en-IN")]));
            });
        });
    }
    return { rows, bold, dark, head };
};
const exportStyleWork = (fmt, style, entries, cycleOf, extra) => {
    const sx = buildStyleScreenRows(style, entries, cycleOf, extra);
    exportRowsFile(fmt, {
        title: `${style?.styleName || "Style"} - Work Details`,
        sub: [`Style ID: ${style?.styleCode || "-"}`, `Order Qty: ${toNum(style?.orderQuantity ?? style?.quantity ?? style?.pieces).toLocaleString("en-IN")} pcs`, style?.garmentType ? `Garment: ${style.garmentType}` : ""].filter(Boolean).join("   |   "),
        rows: sx.rows, bold: sx.bold, dark: sx.dark, head: sx.head, screen: true, grayCol: -1, rightFrom: 3, greenDark: true,
        base: `style-${String(style?.styleCode || style?.styleName || "work").replace(/[^A-Za-z0-9]+/g, "-").toLowerCase()}-work`,
        widths: [0.22, 0.20, 0.22, 0.14, 0.22], rightCols: [3, 4],
    });
};
// ============================================================
// STYLE PAGE PDF — style detail page jaisa layout: header · Operations (combo-wise) · Allocation · cycle-wise operation tables
// ============================================================
const makeStylePagePdfBlob = (m) => {
    // A4 (595 x 842 pt). Layout chhote "virtual" page (W x H) par bana hai aur K se scale hota hai — K = 1.8 => body text 10.4 x 1.8 = ~18.7pt = 25px.
    const K = 1.8, PW = 595, PH = 842, MX = 28, MT = 26, MB = 26, W = (PW - MX * 2) / K, H = (PH - MT - MB) / K, P = 4, BOT = 14; // MX/MT/MB = printer-safe margin (pt) — A4 par kinaare kat'te nahi
    const n2 = (v) => (+v).toFixed(2);
    const rgb = (hex) => { const h = hex.replace("#", ""); return [0, 2, 4].map(i => (parseInt(h.slice(i, i + 2), 16) / 255).toFixed(3)).join(" "); }; // asli rang — pehle har rang black/grey ban jata tha
    const C = { green: TW_GREEN, gdark: "#000000", ink: "#000000", line: "#E5E7EB", dline: "#D6D6DA", soft: "#F1F7F3", tot: "#F6FBF8", row: "#F0FBF4", red: "#DC2626", white: "#FFFFFF", mute: "#000000", pale: "#D5EFDF", head: "#E6EBE8", gray: "#99A2AD", opBg: "#E6F4EA", opLine: "#CBE5D3", subBg: "#F6F7F9", wc: "#334155", hsep: "#B9D9C5" };
    const B = 10.4, RH = 22; // body text size (virtual) · row height
    const pages = [];
    let ops = [], y = 0;
    const rect = (x, yTop, w, h, hex) => ops.push(`${rgb(hex)} rg ${n2(x)} ${n2(H - yTop - h)} ${n2(w)} ${n2(h)} re f`);
    const hline = (yTop, hex, wd = 0.4, x1 = 0, x2 = W) => ops.push(`${rgb(hex)} RG ${wd} w ${n2(x1)} ${n2(H - yTop)} m ${n2(x2)} ${n2(H - yTop)} l S`);
    const vline = (x, y1, y2, hex, wd = 0.4) => ops.push(`${rgb(hex)} RG ${wd} w ${n2(x)} ${n2(H - y1)} m ${n2(x)} ${n2(H - y2)} l S`);
    const pill = (x, yTop, w, h, hex) => {
        const r = h / 2, k = 0.5523 * r, X = x, Y = H - yTop - h;
        ops.push(`${rgb(hex)} rg ${n2(X + r)} ${n2(Y)} m ${n2(X + w - r)} ${n2(Y)} l ${n2(X + w - r + k)} ${n2(Y)} ${n2(X + w)} ${n2(Y + r - k)} ${n2(X + w)} ${n2(Y + r)} c ${n2(X + w)} ${n2(Y + h - r)} l ${n2(X + w)} ${n2(Y + h - r + k)} ${n2(X + w - r + k)} ${n2(Y + h)} ${n2(X + w - r)} ${n2(Y + h)} c ${n2(X + r)} ${n2(Y + h)} l ${n2(X + r - k)} ${n2(Y + h)} ${n2(X)} ${n2(Y + h - r + k)} ${n2(X)} ${n2(Y + h - r)} c ${n2(X)} ${n2(Y + r)} l ${n2(X)} ${n2(Y + r - k)} ${n2(X + r - k)} ${n2(Y)} ${n2(X + r)} ${n2(Y)} c f`);
    };
    // Text: maxW dene par pehle font chhota hota hai (min tak), phir bhi na aaye to ... se katta hai — wrap kabhi nahi
    const text = (str, x, base, size, bold, hex, o = {}) => {
        let t = pdfSan(str), sz = size;
        if (o.maxW) {
            const minSz = o.min || size;
            while (sz > minSz && pdfW(t, sz, bold) > o.maxW)
                sz = Math.max(minSz, +(sz - 0.2).toFixed(2));
            t = pdfFit(t, o.maxW, sz, bold);
        }
        const w = pdfW(t, sz, bold);
        const px = o.right ? x - w : x;
        ops.push(`${rgb(hex)} rg BT /${bold ? "F2" : "F1"} ${sz} Tf ${n2(px)} ${n2(H - base)} Td (${pdfEsc(t)}) Tj ET`);
        return w;
    };
    const newPage = () => { if (ops.length)
        pages.push(ops); ops = []; y = 0; };
    const need = (h) => { if (y + h > H - BOT)
        newPage(); };
    const num = (v) => toNum(v).toLocaleString("en-IN");
    const bl = (top, h) => top + h * 0.68; // text baseline row ke andar
    // ── Page 1: brand + green style header ──
    newPage();
    text(PDF_BRAND.app, P, 15, 11, true, "#000000");
    if (PDF_BRAND.company)
        text(PDF_BRAND.company, W - P, 15, 8, true, "#000000", { right: true, maxW: W - P * 2 - pdfW(PDF_BRAND.app, 11, true) - 10, min: 6 });
    hline(21, "#D5D5D5", 0.6, P, W - P);
    y = 26;
    const qtyTxt = num(m.orderQty);
    const qw = Math.max(pdfW(qtyTxt, 15, true), pdfW("ORDER QTY", 6.5, true));
    text(m.name, P, y + 19, 14, true, C.ink, { maxW: W - P * 2 - qw - 10, min: 9 });
    if (m.sub)
        text(m.sub, P, y + 33, 7.5, false, C.ink, { maxW: W - P * 2 - qw - 10 });
    text(qtyTxt, W - P, y + 19, 15, true, C.ink, { right: true });
    text("ORDER QTY", W - P, y + 33, 6.5, true, C.gray, { right: true });
    y += 42;
    hline(y, C.dline, 0.6);
    const sectionHead = (title) => {
        need(34);
        y += 8;
        text(title, P, y + 15, 13, true, C.ink);
        y += 22;
        hline(y, C.dline, 0.6);
    };
    // ── Operations (screen jaisa): combo → operation (alloc/done) → kaam ki rows ──
    sectionHead("Operations");
    if (!m.blocks.length) {
        need(24);
        text("Koi combo nahi", P, y + 16, B, true, C.mute);
        y += 24;
    }
    const uW = W - P * 2, fr = SWR_FR, fs = fr.reduce((t, v) => t + v, 0);
    const cX = [P]; fr.forEach((v, i) => cX.push(cX[i] + uW * v / fs));
    const money = (v) => "Rs " + toNum(v).toLocaleString("en-IN", { maximumFractionDigits: 2 });
    m.blocks.forEach(b => {
        need(24 + 18 + RH * 2);
        rect(0, y, W, 24, C.green);
        const rtw = text(b.val > 0 ? money(b.val) : "-", W - P, y + 16, 9, true, C.white, { right: true });
        const atw = text(b.alloc > 0 ? "Alloc " + num(b.alloc) : "Alloc -", W - P - rtw - 10, y + 16, 8.5, true, C.white, { right: true });
        text(`${b.title}  |  ${b.ops.length} operations`, P, y + 16, 11, true, C.white, { maxW: W - P * 2 - rtw - atw - 24, min: 7.5 });
        y += 24;
        rect(0, y, W, 18, C.green);
        STYLE_OPS_COLS.slice(0, 3).forEach((l, i) => text(l.toUpperCase(), cX[i], y + 12.5, 7, true, C.white));
        text(STYLE_OPS_COLS[3].toUpperCase(), cX[4] - 4, y + 12.5, 7, true, C.white, { right: true });
        text(STYLE_OPS_COLS[4].toUpperCase(), W - P, y + 12.5, 7, true, C.white, { right: true });
        y += 18;
        b.ops.forEach(o => {
            need(RH * 2);
            rect(0, y, W, RH, C.opBg);
            const aw = text(`${num(o.alloc)}/${num(o.pcs)}`, W - P, bl(y, RH), B, true, C.green, { right: true });
            text(`${o.name}  Rs ${o.rate}`, P, bl(y, RH), B, true, C.green, { maxW: W - P * 2 - aw - 8, min: 7.5 });
            hline(y + RH, C.opLine);
            y += RH;
            o.rows.forEach(r => {
                need(RH);
                text(swrShort(r.cycle), cX[0], bl(y, RH), B, false, C.ink, { maxW: cX[1] - cX[0] - 4, min: 7 });
                text(r.dept, cX[1], bl(y, RH), B, true, C.ink, { maxW: cX[2] - cX[1] - 4, min: 7 });
                text(r.tailor, cX[2], bl(y, RH), B, false, C.ink, { maxW: cX[3] - cX[2] - 4, min: 7 });
                text(num(r.pcs), cX[4] - 4, bl(y, RH), B, false, C.ink, { right: true });
                text(money(r.val), W - P, bl(y, RH), B, true, C.green, { right: true });
                hline(y + RH, C.line);
                y += RH;
            });
        });
        hline(y, C.dline, 0.6);
    });
    y += 7;
    need(20);
    y += 3;
    // ── Allocation: screen ki tarah cycle-wise cards (har card apne page par) ──
    if (!m.cards.length)
        sectionHead("Allocation");
    if (!m.cards.length) {
        need(24);
        text("Abhi koi allocation nahi", P, y + 16, B, true, C.mute);
        y += 24;
    }
    // ── Cycle-wise allocation tables ──
    const xTot = W - P, xPrev = xTot - 46, xNext = xPrev - 46, xCur = xNext - 54;
    m.cards.forEach(a => {
        // Har allocation (combo wali bhi) apne alag page par — upar style ka naam taaki page akela padhne par bhi samajh aaye
        newPage();
        const nm = pdfSan(m.name);
        const nmW = text(nm, P, 15, 9, true, C.ink, { maxW: W - P * 2 - 70, min: 7 });
        if (m.sub)
            text(m.sub, W - P, 15, 7.5, false, C.ink, { right: true, maxW: W - P * 2 - nmW - 12, min: 6 });
        hline(21, C.line, 0.6, P, W - P);
        y = 28;
        need(26 + (a.rows ? 18 + RH : 22));
        rect(0, y, W, 26, C.green);
        const qs = num(a.qty), qwid = pdfW(pdfSan(qs), 10, true), pw = qwid + 14;
        const maxLeft = W - P * 2 - pw - 8;
        let x = P;
        const used = () => x - P;
        const seg = (str, sz) => { const room = maxLeft - used(); if (room < 16)
            return; x += text(str, x, y + 17, sz, true, C.white, { maxW: room, min: 7 }); };
        const sep = () => { if (maxLeft - used() < 24)
            return; vline(x + 6, y + 7, y + 19, C.hsep, 0.8); x += 12; };
        seg(a.dept, B);
        if (a.cycle) {
            sep();
            seg(a.cycle, 9.6);
        }
        if (a.combo) {
            sep();
            seg(a.combo, 9.6);
        }
        pill(W - P - pw, y + 4.5, pw, 17, C.white);
        text(qs, W - P - pw / 2 - qwid / 2, y + 16.5, 10, true, C.gdark);
        y += 26;
        if (!a.rows) {
            text("Combo select nahi hai", P, y + 14, 8, true, C.red);
            y += 22;
            hline(y, C.dline, 0.6);
            return;
        }
        rect(0, y, W, 18, C.soft);
        text(STYLE_ALLOC_COLS[0].toUpperCase(), P, y + 12.5, 7, true, C.ink);
        [[STYLE_ALLOC_COLS[1], xCur], [STYLE_ALLOC_COLS[2], xNext], [STYLE_ALLOC_COLS[3], xPrev], [STYLE_ALLOC_COLS[4], xTot]].forEach(([l, xr]) => text(l.toUpperCase(), xr, y + 12.5, 7, true, C.ink, { right: true }));
        hline(y + 18, C.line);
        y += 18;
        a.rows.forEach(r => {
            need(RH);
            rect(0, y, W, RH, C.opBg); // screen jaisa: operation row hamesha halka green, text green
            text(r[0], P, bl(y, RH), B, true, C.green, { maxW: xCur - 36 - P, min: 7.5 });
            text(num(r[1]), xCur, bl(y, RH), B, true, C.green, { right: true });
            text(num(r[2]), xNext, bl(y, RH), B, true, C.green, { right: true });
            text(num(r[3]), xPrev, bl(y, RH), B, true, C.green, { right: true });
            text(num(r[4]), xTot, bl(y, RH), B, true, C.green, { right: true });
            hline(y + RH, C.line);
            y += RH;
            // Screen jaisa: operation ke neeche us operation ke tailor (ID | pcs | amount), halki neeli row
            const RS = 17;
            (r[5] || []).forEach(t => {
                need(RS);
                rect(0, y, W, RS, C.subBg);
                text(t[0], P, bl(y, RS), 8.6, true, "#000000", { maxW: xCur - 36 - P, min: 7 });
                text(num(t[1]), xPrev, bl(y, RS), 8.6, true, C.wc, { right: true });
                text("Rs " + num(t[2]), xTot, bl(y, RS), 8.6, true, C.green, { right: true });
                y += RS;
            });
            if ((r[5] || []).length)
                hline(y, C.line);
        });
        hline(y, C.dline, 0.6);
    });
    pages.push(ops);
    pages.forEach((pg, i) => {
        ops = pg;
        text(`Page ${i + 1} / ${pages.length}`, W - P, H - 6, 6.5, false, C.mute, { right: true });
    });
    return pdfAssemble(pages, PW, PH, `${K} 0 0 ${K} ${MX} ${MB} cm\n`);
};
// Ek allocation ki operation-wise rows: [op, Current, Next(carry gaya), Prev(carry aaya), Total, [tailor entries]] — Admin card, Manager card, PDF aur Excel sab yahin se
const allocOpRows = (a, cOps, entries = []) => {
    const base = toNum(a.allocatedQty);
    return (cOps || []).map(n => { const o = toNum(a.carryOut?.[n]), i = toNum(a.carryIn?.[n]); return [n, Math.max(0, base - o), o, i, allocOpQty(a, n), opEntriesByName(entries, a, n).map(e => [e.staffId || e.workerName || "-", getEntryPieces(e), Math.round(getEntryAmount(e))])]; });
};
// Style ke allocation cards (screen ke Allocation section jaisa) — PDF aur Excel dono yahin se
const buildStyleAllocCards = (st, allAllocs, companyId, entries = []) => {
    const combos = st.combos || [];
    const styleAllocs = (allAllocs || [])
        .filter(a => a.styleId === st.id && isDeptAlloc(a) && sameCompany(a, companyId))
        .sort((x, y) => String(x.department).localeCompare(String(y.department)) || String(x.cycleKey).localeCompare(String(y.cycleKey)));
    return styleAllocs.map(a => {
        const combo = combos.find(c => c.id === a.comboId);
        const cOps = combo?.opNames || a.comboOps || [];
        return {
            id: a.id, dept: a.department, cycle: a.cycleLabel || getCycleByKey(a.cycleKey)?.label || "",
            combo: a.comboId ? (combo?.name || a.comboName || "") : "", qty: allocDisplayQty(a),
            rows: a.comboId ? allocOpRows(a, cOps, entries) : null,
        };
    });
};
// Style > Operations screen ka model — combo → operation (alloc/done) → kaam ki rows. PDF aur Excel dono yahin se (screen jaisa, koi extra cheez nahi)
const buildStyleOpsModel = (style, entries, cycleOf, allAllocs, companyId) => {
    const st = style || {};
    const combos = st.combos || [];
    const procs = st.processes || [];
    const adminOps = scopedByCompany(MOCK_DB.operations, companyId);
    const rateOf = (n) => procs.find(p => p.name === n)?.pieceRate ?? adminOps.find(o => o.name === n)?.pieceRate ?? 0;
    const wt = buildStyleWorkTree({ ...st, combos }, (entries || []).filter(e => e.styleId === st.id && isCountedEntry(e)), cycleOf);
    const opData = new Map();
    wt.groups.forEach(g => g.ops.forEach(o => opData.set(o.op, o)));
    const inCombo = new Set(combos.flatMap(c => c.opNames || []));
    const cols = [
        ...combos.map(c => ({ key: c.id, title: c.name || "Combo", names: [...(c.opNames || [])] })),
        ...(procs.filter(p => !inCombo.has(p.name)).length ? [{ key: "loose", title: "Combo ke bahar", names: procs.filter(p => !inCombo.has(p.name)).map(p => p.name) }] : []),
    ];
    const leftover = [...opData.keys()].filter(n => !cols.some(c => c.names.includes(n)));
    if (leftover.length) {
        const lc = cols.find(c => c.key === "loose");
        if (lc)
            lc.names = [...lc.names, ...leftover];
        else
            cols.push({ key: "loose", title: "Combo ke bahar", names: leftover });
    }
    const owner = new Map();
    cols.forEach(c => c.names.forEach(n => { if (!owner.has(n)) owner.set(n, c.key); }));
    const allocOf = (n) => (allAllocs || []).filter(a => a.styleId === st.id && isDeptAlloc(a) && sameCompany(a, companyId) && allocCoversOp(a, n)).reduce((t, a) => t + allocOpQty(a, n), 0);
    const blocks = cols.map(c => {
        const ops = c.names.map(n => {
            const d = owner.get(n) === c.key ? (opData.get(n) || null) : null;
            return { name: n, rate: rateOf(n), alloc: allocOf(n), pcs: d ? d.pcs : 0, rows: d ? d.rows : [] };
        });
        return { key: c.key, title: c.title, ops, alloc: Math.max(0, ...ops.map(o => o.alloc)), val: roundMoney(ops.reduce((t, o) => t + o.rows.reduce((x, r) => x + r.val, 0), 0)) };
    });
    return { blocks };
};
const exportStylePagePdf = (style, allAllocs, companyId, entries = [], workEntries = null, cycleOf = null) => {
    const st = style || {};
    const blocks = buildStyleOpsModel(st, workEntries || entries, cycleOf, allAllocs, companyId).blocks;
    const cards = buildStyleAllocCards(st, allAllocs, companyId, entries);
    const blob = makeStylePagePdfBlob({
        name: st.styleName || "Style",
        sub: [st.styleCode, st.garmentType].filter(Boolean).join("   |   "),
        orderQty: st.orderQuantity ?? st.totalQuantity, blocks, cards,
    });
    saveBlobAs(blob, `style-${String(st.styleCode || st.styleName || "details").replace(/[^A-Za-z0-9]+/g, "-").toLowerCase()}-details.pdf`);
};
const isMonthKey = (k) => /^\d{4}-\d{2}$/.test(String(k || ""));
const isHalfKey = (k) => /^\d{4}-\d{2}-[12]$/.test(String(k || ""));
// Cycle type badalne par Work Allocations naye cycle keys mein convert hoti hain.
// 15days -> monthly: ek mahine ke dono halves ki qty jud jaati hai (entries pehle se allocation ke andar thi, isliye safe).
// monthly -> 15days: qty ~barabar do halves mein baanti jaati hai, LEKIN har half ko kam se kam utni qty milti hai
//   jitni uss half mein kisi ek operation ki entries pehle se ho chuki hain (allocUsedQty ka rule) — taaki koi entry
//   allocation se upar na chali jaaye. Agar dono halves ki zaroorat ka jod monthly allocation se zyada hai (alag-alag
//   operations alag halves mein bhare), to wo allocation "conflict" ban jaati hai aur cycle change block hota hai.
// Return: { allocs, conflicts }  — conflicts khaali ho tabhi allocs apply karne hain.
const remapAllocations = (allocs, toType, entries) => {
    const list = allocs || [];
    const out = [];
    const conflicts = [];
    if (toType === "monthly") {
        const idx = {};
        list.forEach(a => {
            if (!isHalfKey(a.cycleKey)) {
                out.push(a);
                return;
            }
            const month = a.cycleKey.slice(0, 7);
            const gk = `${a.companyId || ""}|${a.styleId}|${a.department}|${month}|${a.comboId || ""}`;
            if (idx[gk] === undefined) {
                idx[gk] = out.length;
                out.push({ ...a, cycleKey: month, cycleLabel: getCycleByKey(month)?.label || a.cycleLabel, allocatedQty: Number(a.allocatedQty) || 0 });
            }
            else {
                const t = out[idx[gk]];
                const mergeMap = (x, y) => { const r = { ...(x || {}) }; Object.entries(y || {}).forEach(([k, v]) => { r[k] = (r[k] || 0) + toNum(v); }); return r; };
                out[idx[gk]] = { ...t, allocatedQty: (Number(t.allocatedQty) || 0) + (Number(a.allocatedQty) || 0), carryIn: mergeMap(t.carryIn, a.carryIn), carryOut: mergeMap(t.carryOut, a.carryOut) };
            }
        });
        return { allocs: out, conflicts };
    }
    list.forEach(a => {
        if (!isMonthKey(a.cycleKey)) {
            out.push(a);
            return;
        }
        const total = Number(a.allocatedQty) || 0;
        const k1 = `${a.cycleKey}-1`, k2 = `${a.cycleKey}-2`;
        const base = { styleId: a.styleId, department: a.department, companyId: a.companyId, comboId: a.comboId, comboOps: a.comboOps };
        const need1 = allocUsedQty(entries, { ...base, cycleKey: k1 }); // pehle half mein ab tak ki sabse badi operation-qty
        const need2 = allocUsedQty(entries, { ...base, cycleKey: k2 });
        if (need1 + need2 > total) {
            conflicts.push({ alloc: a, need1, need2, total });
            return;
        }
        let first = Math.ceil(total / 2);
        if (first < need1)
            first = need1; // pehle half ko uski entries se kam nahi milni chahiye
        if (total - first < need2)
            first = total - need2; // doosre half ko bhi nahi
        const second = total - first;
        if (first > 0)
            out.push({ ...a, cycleKey: k1, cycleLabel: getCycleByKey(k1)?.label || a.cycleLabel, allocatedQty: first });
        if (second > 0)
            out.push({ ...a, carryIn: first > 0 ? {} : a.carryIn, carryOut: first > 0 ? {} : a.carryOut, id: first > 0 ? uid("da") : a.id, cycleKey: k2, cycleLabel: getCycleByKey(k2)?.label || a.cycleLabel, allocatedQty: second });
    });
    return { allocs: out, conflicts };
};
